INSERT INTO work_queue (id,task_type,payload,status,created_at) SELECT 'pending-backfill-guard','metadata','{}','guard_failed',unixepoch() WHERE NOT ((SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-3289ebb925dd456ba14e6bfd5f5685f8' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1)=5 AND NOT EXISTS (SELECT 1 FROM albums WHERE id='al-04d3a5af95307e73856b859df5fb4151') AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-upload-0eb138eb-495','sm-upload-1fa15574-293','sm-upload-884d87d8-f8d','sm-upload-8d28b118-c2d','sm-upload-c2754cf8-e65') GROUP BY lower(trim(title)) HAVING COUNT(*)>1) AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-upload-0eb138eb-495','sm-upload-1fa15574-293','sm-upload-884d87d8-f8d','sm-upload-8d28b118-c2d','sm-upload-c2754cf8-e65') AND track IS NOT NULL GROUP BY COALESCE(disc,0),track HAVING COUNT(*)>1) AND (SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-3289ebb925dd456ba14e6bfd5f5685f8' AND sm.album_id!='pending-uploads')=0 AND (SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-3289ebb925dd456ba14e6bfd5f5685f8' AND sm.album_id!='pending-uploads' AND sm.id NOT IN (''))=0 AND (SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE sm.id IN ('') AND sm.album_id IN ('') AND se.source_id='r2-local' AND se.parent_id='se-3289ebb925dd456ba14e6bfd5f5685f8' AND lower(si.suffix)='wav')=0);
